insert into app.business_rule_catalog(rule_key,domain,title,description,source,precedence,enforcement,status,test_status,source_ref,metadata)
values
('USER-001','users','Owner membership is protected','The organization owner cannot be demoted or deactivated from the standard membership administration command.','approved_v2',100,'command','active','tested','private.command_update_membership_admin','{"qa":"owner update rejected with rollback"}'::jsonb),
('USER-002','users','Membership administration is command-driven','Invitations, invitation revocation and membership changes are authorized by Users module write permission and are not performed by direct browser table writes.','approved_v2',100,'command','active','tested','v2_create_invitation / v2_revoke_invitation / v2_update_membership','{"qa":"create-query-revoke rollback"}'::jsonb),
('CAL-001','calendar','Calendar is a unified projection','Calendar reads canonical sessions, matches, programs and manual club events instead of duplicating them into a separate calendar store.','approved_v2',100,'workflow','active','tested','private.query_calendar','{"sources":["sessions","matches","programs","club_events"]}'::jsonb),
('CAL-002','calendar','Manual calendar events use commands','Manual meetings, activations and administrative events are created through an authorized calendar command with validated title, date, type and status.','approved_v2',100,'command','active','tested','private.command_upsert_club_event','{"qa":"create-query-invalid-title rollback"}'::jsonb)
